<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\LiveDisplaySessionService;Auth::requireAdmin();$pdo=Database::connection();$test=($_GET['mode']??$_POST['mode']??'real')==='test';$eventId=(int)($_GET['event_id']??$_POST['event_id']??0);$eventTable=$test?'bdc_test_events':'bdc_events';$roundTable=$test?'bdc_test_scoring_rounds':'bdc_scoring_rounds';$e=$pdo->prepare("SELECT id,name FROM {$eventTable} WHERE id=:id");$e->execute(['id'=>$eventId]);$event=$e->fetch();if(!$event){http_response_code(404);exit('Event not found.');}$notice='';$token='';if($_SERVER['REQUEST_METHOD']==='POST'&&Csrf::verify($_POST['_csrf']??null)){if(($_POST['action']??'')==='generate'){$token=LiveDisplaySessionService::generate($pdo,$eventId,$test,(int)(Auth::user()['id']??0));$notice='New Live Display link generated.';}else{if(!LiveDisplaySessionService::forEvent($pdo,$eventId,$test))$token=LiveDisplaySessionService::generate($pdo,$eventId,$test,(int)(Auth::user()['id']??0));LiveDisplaySessionService::update($pdo,$eventId,$test,$_POST,(int)(Auth::user()['id']??0));$notice='Remote display updated.';}}$session=LiveDisplaySessionService::forEvent($pdo,$eventId,$test);$roundsStmt=$pdo->prepare("SELECT id,division,round_type,status FROM {$roundTable} WHERE event_id=:e ORDER BY division,FIELD(round_type,'heats','semifinal','final'),id");$roundsStmt->execute(['e'=>$eventId]);$rounds=$roundsStmt->fetchAll();$displayUrl=$token!==''?url('live-display/?token='.rawurlencode($token)):'';?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Remote Live Display Control</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><div class="d-flex justify-content-between"><div><div class="text-danger fw-bold"><?=$test?'TEST ':''?>REMOTE PROJECTOR</div><h1 class="h3"><?=e($event['name'])?></h1></div><a class="btn btn-outline-dark align-self-start" href="<?=$test?'test-index.php':'./'?>">Back</a></div><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><div class="card shadow-sm mb-3"><div class="card-body"><h2 class="h5">Projector PC Link</h2><?php if($displayUrl):?><div class="input-group mb-2"><input class="form-control" value="<?=e($displayUrl)?>" readonly id="displayUrl"><button class="btn btn-outline-primary" onclick="navigator.clipboard.writeText(displayUrl.value)">Copy</button><a class="btn btn-primary" target="_blank" href="<?=e($displayUrl)?>">Open</a></div><?php else:?><p class="text-muted">Generate a link and give it to the projector operator. They open it once and leave it full-screen.</p><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="event_id" value="<?=$eventId?>"><input type="hidden" name="mode" value="<?=$test?'test':'real'?>"><button class="btn btn-dark" name="action" value="generate">Generate / Regenerate Live Display Link</button></form></div></div><form method="post" class="card shadow-sm"><div class="card-body"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="event_id" value="<?=$eventId?>"><input type="hidden" name="mode" value="<?=$test?'test':'real'?>"><h2 class="h5">Remote Control</h2><label class="form-label">Competition Round</label><select name="round_id" class="form-select mb-3"><option value="">Holding Screen</option><?php foreach($rounds as $r):?><option value="<?=(int)$r['id']?>" <?=($session['current_round_id']??0)==$r['id']?'selected':''?>><?=e(ucwords(str_replace('_',' ',$r['division'])))?> · <?=e(ucfirst($r['round_type']))?></option><?php endforeach;?></select><div class="d-flex flex-wrap gap-2 mb-3"><?php foreach(['holding'=>'Holding','judges'=>'Judges','competitors'=>'Competitors','scoring'=>'Scoring','callbacks'=>'Callbacks','finalists'=>'Finalists','results'=>'Final Ranking','winners'=>'Winners'] as $v=>$l):?><button class="btn <?=($session['screen_type']??'holding')===$v?'btn-danger':'btn-outline-danger'?>" name="screen_type" value="<?=$v?>"><?=e($l)?></button><?php endforeach;?></div><div class="row g-2"><div class="col-md-3"><label class="form-label">Page</label><input class="form-control" name="page_number" type="number" min="1" value="<?=(int)($session['page_number']??1)?>"></div><div class="col-md-3"><label class="form-label">Auto Page</label><select class="form-select" name="auto_page"><option value="1" <?=!isset($session['auto_page'])||$session['auto_page']?'selected':''?>>On</option><option value="0" <?=isset($session['auto_page'])&&!$session['auto_page']?'selected':''?>>Off</option></select></div><div class="col-md-3"><label class="form-label">Delay</label><select class="form-select" name="page_delay_seconds"><?php foreach([5,10,15,20,30,45,60] as $d):?><option value="<?=$d?>" <?=($session['page_delay_seconds']??15)===$d?'selected':''?>><?=$d?> seconds</option><?php endforeach;?></select></div></div><div class="small text-muted mt-2">Default is 15 seconds. Auto paging applies only to Competitors, Callbacks and Finalists when more than one page exists.</div></div></form></main></body></html>